import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Canonical surface as the arrow calculus — design detail","description":"","frontmatter":{"title":"Canonical surface as the arrow calculus — design detail","type":"design","date":"2026-09-14T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","refs":["ADR-0100"]},"headers":[],"relativePath":"handl/project/design/0100-canonical-term-arrows.md","filePath":"vendored/handl/project/design/0100-canonical-term-arrows.md"}`),a={name:`handl/project/design/0100-canonical-term-arrows.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="canonical-surface-as-the-arrow-calculus-—-design-detail" tabindex="-1">Canonical surface as the arrow calculus — design detail <a class="header-anchor" href="#canonical-surface-as-the-arrow-calculus-—-design-detail" aria-label="Permalink to “Canonical surface as the arrow calculus — design detail”">​</a></h1><p>Moved verbatim from ADR-0100 (ADR-0161 size budget). The ADR carries the rules; this page carries the mechanism, tables and rationale.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Make the canonical internal form the arrow-calculus <code>Term</code> with no <code>function</code>, <code>call</code>, <code>block</code>, <code>assign</code>, or <code>object</code> nodes. Every canonical program lowers to a <code>Term</code> graph built from the existing constructors:</p><ul><li><code>Arr</code> — pure constant arrow / lifted pure operation (<code>arr</code>)</li><li><code>Const</code> — pure constant value (used as an argument)</li><li><code>Op</code> — named native/foreign operation</li><li><code>Seq</code> — composition (<code>&gt;&gt;&gt;</code>)</li><li><code>First</code> — act on first component</li><li><code>Second</code> — act on second component (derived from <code>first</code> + <code>arr swap</code>)</li><li><code>Choice</code> — branch on <code>Either</code></li><li><code>Loop</code> — feedback</li><li><code>App</code> — higher-order arrow application</li><li><code>Handle</code> — capability handler</li></ul><p>Canonical lowering:</p><ul><li><code>x ~&gt; body</code> → point-free <code>Term</code> sugar. The parser/lowerer eliminates the variable <code>x</code> using <code>arr</code> of pure functions and the product combinators (<code>first</code>, <code>second</code>, <code>&amp;&amp;&amp;</code>, <code>***</code>) as in the research prototype&#39;s &quot;Lambda-to-Arrow Translation&quot;. If <code>body</code> is not point-free expressible, it is lifted to a pure <code>FunctionValue</code> and wrapped in <code>Arr</code>.</li><li><code>f(x)</code> / <code>f y</code> → <code>App { callee: f, args: [x] }</code> when <code>f</code> is dynamic, or <code>Seq</code> when <code>f</code> is a known arrow.</li><li><code>do { a = b; c }</code> → <code>Seq(b, ...)</code> with the result threaded through the input. <code>=</code> is not a semantic node.</li><li><code>{ first: a, last: b }</code> → an <code>Op</code>/<code>Arr</code> that constructs the record from the arrow inputs.</li><li><code>a + b</code>, <code>a * b</code> → <code>Op { &quot;math.add&quot; / &quot;math.mul&quot;, ... }</code>.</li><li>literals (<code>10</code>, <code>7</code>) → <code>Const</code>.</li></ul><p>The existing generic AST/eval runtime is replaced or augmented by an engine that interprets <code>Term</code> directly. <code>eval.yaml</code> becomes a description of how each <code>Term</code> constructor is interpreted.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The canonical surface syntax (<code>~&gt;</code>, <code>&gt;&gt;&gt;</code>, <code>***</code>, <code>&amp;&amp;&amp;</code>, <code>do</code>, <code>=</code>) is intended to be arrow-native, but the current runtime keeps a mixed AST with <code>block</code>, <code>assign</code>, <code>function</code>, <code>call</code>, and <code>object</code> nodes. Those are not arrow calculus forms; they are lambda-style concepts that the design intended to eliminate.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>Term</code> does <strong>not</strong> gain <code>Lam</code> or <code>Var</code>. The kernel stays combinator-based.</li><li><code>~&gt;</code> and <code>do</code> are surface sugar, not semantic forms.</li><li>A canonical-to-<code>Term</code> lowerer must implement the lambda-to-arrow</li><li>All canonical tooling (parser, typechecker, formatter, linter) must produce</li><li>Runtime eval engines and back-end compilers (JS, LLVM) interpret <code>Term</code></li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0100-canonical-term-arrows.html"><code>design/0100-canonical-term-arrows.md</code></a>.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};